            {
                CloseButtonClick();
            }
        }

        /// <summary>
        /// 팝업 닫기 액션 추가
        /// </summary>
        public static void AddClosePopUpAction(Action action)
        {
            if (action != null)
            {
                closePopUpActionList.Add(action);
                // if (_isDebugMode) Debug.Log($"팝업 닫기 액션 등록됨 (현재 {closePopUpActionList.Count}개)");
            }
            else
            {
                // if (_isDebugMode) Debug.LogError(string.Format(ErrorNullReference, "액션"));
            }
        }

        /// <summary>
        /// 팝업 닫기 버튼 클릭 처리
        /// </summary>
        private void CloseButtonClick()
        {
            if (closePopUpActionList.Count > 0)
            {
                int lastIndex = closePopUpActionList.Count - 1;
                Action lastAction = closePopUpActionList[lastIndex];

                closePopUpActionList.RemoveAt(lastIndex);
                lastAction?.Invoke();

                if (_isDebugMode) Debug.Log($"팝업 닫기 실행 (남은 팝업: {closePopUpActionList.Count}개)");
            }
            else
            {
                if (_isDebugMode) Debug.Log("닫을 팝업이 없습니다.");
            }
        }

        #endregion

        #region UI 업데이트 메서드

        /// <summary>
        /// 화면에 재화 정보 업데이트
        /// </summary>
        private void UpdateCurrencyDisplay()
        {
            if (playerDataManagerDontdesytoy?.scritpableobjPlayerData == null)
            {
                if (_isDebugMode) Debug.LogError(string.Format(ErrorNullReference, "플레이어 데이터"));
                return;
            }

            if (gold != null)
                gold.text = playerDataManagerDontdesytoy.scritpableobjPlayerData.currency1.ToString("N0");

            if (dia != null)
                dia.text = playerDataManagerDontdesytoy.scritpableobjPlayerData.currency2.ToString("N0");

            if (_isDebugMode) Debug.Log("재화 정보 업데이트 완료");
        }

        #endregion

        #region 버튼 콜백 함수

        /// <summary>
        /// 시작 버튼 콜백 - 게임 선택 팝업 표시
        /// </summary>
        private void func_startBtn()
        {
            if (_isDebugMode) Debug.Log("게임 선택 팝업");

            if (cgamePopUp != null)
            {
                cgamePopUp.SetActive(true);
                AddClosePopUpAction(() => cgamePopUp.SetActive(false));
            }
            else
                if (_isDebugMode) Debug.LogError(string.Format(ErrorNullReference, "게임 선택 팝업"));
        }

        /// <summary>
        /// 튜토리얼 버튼 콜백 - 기본 튜토리얼 시작
        /// </summary>
        private void func_tutorialBtn()
        {
            if (_isDebugMode) Debug.Log("튜토리얼 시작");
            // TODO: 튜토리얼 씬으로 이동하거나 가이드 표시
            if (SceneLoader.Instace != null)
            {
                SceneLoader.Instace.LoadScene("Tutorial");
            }
        }

        /// <summary>
        /// 옵션 버튼 콜백 - 옵션 팝업 표시
        /// </summary>
        private void func_optionBtn()
        {
            if (optionPopupPrefab != null)
            {
                // 이미 열린 팝업이 있으면 닫기
                if (currentOptionPopup != null)
                {
                    Destroy(currentOptionPopup.gameObject);
                    currentOptionPopup = null;
                }

                // 새 옵션 팝업 인스턴스 생성
                currentOptionPopup = Instantiate(optionPopupPrefab, transform.parent);

                // 팝업 닫기 액션 등록
                AddClosePopUpAction(() => {
                    if (currentOptionPopup != null)
                    {
                        Destroy(currentOptionPopup.gameObject);
                        currentOptionPopup = null;
                    }
                });

                if (_isDebugMode) Debug.Log("옵션 팝업 표시");
            }
            else
                if (_isDebugMode) Debug.LogError(string.Format(ErrorNullReference, "옵션 팝업 프리팹"));
        }

        #endregion

        #region 게임 진행 함수

        /// <summary>
        /// 게임 실행 - 씬 전환
        /// </summary>
        private void VamSerlikeStart()
        {
            if (SceneLoader.Instace != null)
            {
                SceneLoader.Instace.LoadScene("VamSerlike");
                if (_isDebugMode) Debug.Log("런게임 씬으로 전환");
            }
            else
            {
                if (_isDebugMode) Debug.LogError(string.Format(ErrorNullReference, "씬 로더"));
            }
        }

        #endregion
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace DogGuns_Games
{
    public class SceneLoader : MonoBehaviour
    {
        protected static SceneLoader instance;

        public static SceneLoader Instace
        {
            get
            {
                if (instance == null)
                {
                    var obj = FindAnyObjectByType<SceneLoader>();
                    if (obj != null)
                    {
                        instance = obj;
                    }
                    else
                    {
                        instance = Create();
                    }
                }

                return instance;
            }
            private set { instance = value; }
        }

        [SerializeField] private CanvasGroup sceneLoadferCanvasGroup;
        [SerializeField] private Slider progressbar;

        //todo: 하이라이어키 드롭다운으로  SceneAsset 변수가 참조 가능하도록




        private string loadSceneName;

        public static SceneLoader Create()
        {
            var SeneLoadprefeb = Resources.Load<SceneLoader>("SceneLoader");
            return Instantiate(SeneLoadprefeb);
        }

        private void Awake()
        {
            if (instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);
        }

        public void LoadScene(string SceneName)
        {
            gameObject.SetActive(true);
            SceneManager.sceneLoaded += LoadSceneEnd;
            loadSceneName = SceneName;
            StartCoroutine(Load(SceneName));
            Debug.Log("Scene change activie");
        }

        private IEnumerator Load(string sceneName)
        {
            progressbar.value = 0f;
            yield return StartCoroutine(Fade(true));

            AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);
            op.allowSceneActivation = false;

            float timer = 0.0f;
            while (!op.isDone)
            {
                yield return null;
                timer += Time.unscaledDeltaTime;
                if (op.progress < 0.9f)
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, op.progress, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= op.progress)
                    {
                        timer = 0f;
                    }
                }
                else
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, 1f, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= 0.9999f)
                    {
                        op.allowSceneActivation = true;
                        yield break;
                    }
                }
            }
        }


        private void LoadSceneEnd(Scene scene, LoadSceneMode loadSceneMode)
        {
            if (scene.name == loadSceneName)
            {
                StartCoroutine(Fade(false));
                SceneManager.sceneLoaded -= LoadSceneEnd;
            }
        }

        private IEnumerator Fade(bool isFadeIn)
        {
            float timer = 0f;

            while (timer <= 1f)
            {
                yield return null;
                timer += Time.unscaledDeltaTime * 2f;
                sceneLoadferCanvasGroup.alpha = Mathf.Lerp(isFadeIn ? 0 : 1, isFadeIn ? 1 : 0, timer);
            }

            if (!isFadeIn)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace DogGuns_Games
{
    public class SceneLoader : MonoBehaviour
    {
        protected static SceneLoader instance;

        public static SceneLoader Instace
        {
            get
            {
                if (instance == null)
                {
                    var obj = FindAnyObjectByType<SceneLoader>();
                    if (obj != null)
                    {
                        instance = obj;
                    }
                    else
                    {
                        instance = Create();
                    }
                }

                return instance;
            }
            private set { instance = value; }
        }

        [SerializeField] private CanvasGroup sceneLoadferCanvasGroup;
        [SerializeField] private Slider progressbar;

        [Header("Scene References")]
        [SerializeField] private SceneReference[] sceneReferences;

        [System.Serializable]
        public class SceneReference
        {
            public string sceneName;

            #if UNITY_EDITOR
            [SerializeField] private UnityEditor.SceneAsset sceneAsset;

            public UnityEditor.SceneAsset SceneAsset
            {
                get => sceneAsset;
                set
                {
                    sceneAsset = value;
                    sceneName = sceneAsset != null ? sceneAsset.name : "";
                }
            }
            #endif
        }

        // 자주 사용되는 씬들을 미리 정의
        [Header("Quick Scene Access")]
        [SerializeField] private SceneReference lobbyScene;
        [SerializeField] private SceneReference gameScene;
        [SerializeField] private SceneReference settingsScene;

        private string loadSceneName;

        public static SceneLoader Create()
        {
            var SeneLoadprefeb = Resources.Load<SceneLoader>("SceneLoader");
            return Instantiate(SeneLoadprefeb);
        }

        private void Awake()
        {
            if (instance != this)
            {
                Destroy(gameObject);
                return;
            }

            DontDestroyOnLoad(gameObject);
        }

        public void LoadScene(string SceneName)
        {
            gameObject.SetActive(true);
            SceneManager.sceneLoaded += LoadSceneEnd;
            loadSceneName = SceneName;
            StartCoroutine(Load(SceneName));
            Debug.Log("Scene change activie");
        }

        /// <summary>
        /// SceneReference를 통해 씬을 로드합니다.
        /// </summary>
        public void LoadScene(SceneReference sceneRef)
        {
            if (sceneRef != null && !string.IsNullOrEmpty(sceneRef.sceneName))
            {
                LoadScene(sceneRef.sceneName);
            }
            else
            {
                Debug.LogError("SceneReference가 유효하지 않습니다!");
            }
        }

        /// <summary>
        /// 로비 씬으로 이동합니다.
        /// </summary>
        public void LoadLobbyScene()
        {
            LoadScene(lobbyScene);
        }

        /// <summary>
        /// 게임 씬으로 이동합니다.
        /// </summary>
        public void LoadGameScene()
        {
            LoadScene(gameScene);
        }

        /// <summary>
        /// 설정 씬으로 이동합니다.
        /// </summary>
        public void LoadSettingsScene()
        {
            LoadScene(settingsScene);
        }

        /// <summary>
        /// 씬 이름으로 SceneReference를 찾습니다.
        /// </summary>
        public SceneReference FindSceneReference(string sceneName)
        {
            if (sceneReferences != null)
            {
                foreach (var sceneRef in sceneReferences)
                {
                    if (sceneRef.sceneName == sceneName)
                        return sceneRef;
                }
            }
            return null;
        }

        private IEnumerator Load(string sceneName)
        {
            progressbar.value = 0f;
            yield return StartCoroutine(Fade(true));

            AsyncOperation op = SceneManager.LoadSceneAsync(sceneName);
            op.allowSceneActivation = false;

            float timer = 0.0f;
            while (!op.isDone)
            {
                yield return null;
                timer += Time.unscaledDeltaTime;
                if (op.progress < 0.9f)
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, op.progress, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= op.progress)
                    {
                        timer = 0f;
                    }
                }
                else
                {
                    float targetProgress = Mathf.Lerp(progressbar.value, 1f, timer);
                    progressbar.value = targetProgress;
                    if (progressbar.value >= 0.9999f)
                    {
                        op.allowSceneActivation = true;
                        yield break;
                    }
                }
            }
        }


        private void LoadSceneEnd(Scene scene, LoadSceneMode loadSceneMode)
        {
            if (scene.name == loadSceneName)
            {
                StartCoroutine(Fade(false));
                SceneManager.sceneLoaded -= LoadSceneEnd;
            }
        }

        private IEnumerator Fade(bool isFadeIn)
        {
            float timer = 0f;

            while (timer <= 1f)
            {
                yield return null;
                timer += Time.unscaledDeltaTime * 2f;
                sceneLoadferCanvasGroup.alpha = Mathf.Lerp(isFadeIn ? 0 : 1, isFadeIn ? 1 : 0, timer);
            }

            if (!isFadeIn)
            {
                gameObject.SetActive(false);
            }
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;


public class SoundManager : MonoBehaviour
{
    #region 싱글톤
    private static SoundManager _instance;
    public static SoundManager Instance
    {
        get
        {
            if (_instance == null)
            {
                // 씬에서 SoundManager를 찾아봅니다.
                _instance = FindFirstObjectByType<SoundManager>();
                // 씬에 SoundManager가 없다면, 새로 생성하지 않고 경고를 출력합니다.
                // SoundManager는 씬에 미리 배치하고 SoundData를 할당해야 합니다.
                if (_instance == null)
                {
                    Debug.LogError("SoundManager instance not found in the scene. Please add SoundManager to your scene and assign SoundData.");
                }
            }
            return _instance;
        }
    }
    #endregion

    #region 변수 및 필드
    [SerializeField] private SoundData soundData; // 인스펙터에서 할당할 SoundData

    AudioSource[] _audioSources = new AudioSource[(int)Sound.Max];
    Dictionary<string, AudioClip> _audioClips = new Dictionary<string, AudioClip>();
    private float _effectsoundVolum = 1.0f;
    private float _bgmSoundVolum = 1.0f;

    #endregion

    #region 정적 메서드

    // 정적 호출 지원
    public static void PlaySound(Sound type, string clipName, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipName, type, pitch, loop);
    }

    public static void PlaySound(Sound type, SoundKeys clipKey, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipKey.ToString(), type, pitch, loop);
    }

    #endregion

    #region 초기화 메서드

    private void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Destroy(gameObject);
            return;
        }
        _instance = this;
        Init();
        DontDestroyOnLoad(gameObject);
    }

    public void Init()
    {
        if (_audioSources[0] != null) return; // 이미 초기화된 경우 중복 방지

        GameObject root = new GameObject { name = "Sound" };
        root.transform.parent = transform; // SoundManager의 자식으로 관리

        string[] SoundNames = System.Enum.GetNames(typeof(Sound));
        for (int i = 0; i < SoundNames.Length - 1; i++)
        {
            GameObject go = new GameObject { name = SoundNames[i] };
            _audioSources[i] = go.AddComponent<AudioSource>();
            go.transform.parent = root.transform;
        }
        _audioSources[(int)Sound.BGM].loop = true;

        // 할당된 SoundData에서 오디오 클립 초기화
        if (soundData != null)
        {
            foreach (var audioInfo in soundData.audioClips)
            {
                if (!_audioClips.ContainsKey(audioInfo.key))
                {
                    _audioClips.Add(audioInfo.key, audioInfo.clip);
                }
            }
        }
        else
        {
            Debug.LogError("SoundData가 SoundManager에 할당되지 않았습니다. 인스펙터에서 할당해주세요.");
        }
    }

    public void Clear()
    {
        foreach (AudioSource audioSource in _audioSources)
        {
            if (audioSource == null) continue;
            audioSource.clip = null;
            audioSource.Stop();
        }
        _audioClips.Clear();
    }

    #endregion

    #region 오디오 재생 메서드

    public void Play(AudioClip audioClip, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        if (audioClip == null)
            return;

        AudioSource audioSource = _audioSources[(int)type];
        if (audioSource == null) return;

        audioSource.pitch = pitch;

        if (type == Sound.BGM)
        {
            if (audioSource.isPlaying)
                audioSource.Stop();
            audioSource.volume = _bgmSoundVolum;
            audioSource.loop = loop;
            audioSource.clip = audioClip;
            audioSource.Play();
            //성공 로그 출력 
            Debug.Log($"Playing BGM: {audioClip.name} with volume: {_bgmSoundVolum}");
        }
        else // Effect
        {
            audioSource.volume = _effectsoundVolum;
            audioSource.loop = false;
            audioSource.PlayOneShot(audioClip);
        }
    }

    public void Play(string path, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        AudioClip audioClip = GetAudioClip(path);
        Play(audioClip, type, pitch, loop);
    }

    #endregion

    #region 유틸리티 메서드

    public void VolumSet(Sound type = Sound.SFX, float volum = 1.0f)
    {
        if (type == Sound.BGM)
        {
            _bgmSoundVolum = volum;
            // 현재 재생 중인 BGM의 볼륨을 즉시 업데이트
            if (_audioSources[(int)Sound.BGM] != null)
            {
                _audioSources[(int)Sound.BGM].volume = _bgmSoundVolum;
            }
        }
        else if (type == Sound.SFX)
        {
            _effectsoundVolum = volum;
            // SFX는 PlayOneShot을 사용하므로 다음 재생부터 적용됨

            if (_audioSources[(int)Sound.SFX] != null)
            {
                _audioSources[(int)Sound.SFX].volume = _effectsoundVolum;
            }

            //Debug.Log($"SFX volume updated to: {_effectsoundVolum}");
        }
    }

    AudioClip GetAudioClip(string key)
    {
        if (_audioClips.TryGetValue(key, out AudioClip audioClip))
        {
            return audioClip;
        }

        Debug.LogWarning($"AudioClip not found: {key}");
        return null;
    }

    #endregion
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;


public class SoundManager : MonoBehaviour
{
    #region 싱글톤
    private static SoundManager _instance;
    public static SoundManager Instance
    {
        get
        {
            if (_instance == null)
            {
                // 씬에서 SoundManager를 찾아봅니다.
                _instance = FindFirstObjectByType<SoundManager>();
                // 씬에 SoundManager가 없다면, 새로 생성하지 않고 경고를 출력합니다.
                // SoundManager는 씬에 미리 배치하고 SoundData를 할당해야 합니다.
                if (_instance == null)
                {
                    Debug.LogError("SoundManager instance not found in the scene. Please add SoundManager to your scene and assign SoundData.");
                }
            }
            return _instance;
        }
    }
    #endregion

    #region 변수 및 필드
    [SerializeField] private SoundData soundData; // 인스펙터에서 할당할 SoundData

    AudioSource[] _audioSources = new AudioSource[(int)Sound.Max];
    Dictionary<string, AudioClip> _audioClips = new Dictionary<string, AudioClip>();
    private float _effectsoundVolum = 1.0f;
    private float _bgmSoundVolum = 1.0f;

    #endregion

    #region 정적 메서드

    // 정적 호출 지원
    public static void PlaySound(Sound type, string clipName, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipName, type, pitch, loop);
    }

    public static void PlaySound(Sound type, SoundKeys clipKey, bool loop = false, float pitch = 1.0f)
    {
        Instance.Play(clipKey.ToString(), type, pitch, loop);
    }

    #endregion

    #region 초기화 메서드

    private void Awake()
    {
        if (_instance != null && _instance != this)
        {
            Destroy(gameObject);
            return;
        }
        _instance = this;
        Init();
        DontDestroyOnLoad(gameObject);
    }

    public void Init()
    {
        if (_audioSources[0] != null) return; // 이미 초기화된 경우 중복 방지

        GameObject root = new GameObject { name = "Sound" };
        root.transform.parent = transform; // SoundManager의 자식으로 관리

        string[] SoundNames = System.Enum.GetNames(typeof(Sound));
        for (int i = 0; i < SoundNames.Length - 1; i++)
        {
            GameObject go = new GameObject { name = SoundNames[i] };
            _audioSources[i] = go.AddComponent<AudioSource>();
            go.transform.parent = root.transform;
        }
        _audioSources[(int)Sound.BGM].loop = true;

        // 할당된 SoundData에서 오디오 클립 초기화
        if (soundData != null)
        {
            foreach (var audioInfo in soundData.audioClips)
            {
                if (!_audioClips.ContainsKey(audioInfo.key))
                {
                    _audioClips.Add(audioInfo.key, audioInfo.clip);
                }
            }
        }
        else
        {
            Debug.LogError("SoundData가 SoundManager에 할당되지 않았습니다. 인스펙터에서 할당해주세요.");
        }
    }

    public void Clear()
    {
        foreach (AudioSource audioSource in _audioSources)
        {
            if (audioSource == null) continue;
            audioSource.clip = null;
            audioSource.Stop();
        }
        _audioClips.Clear();
    }

    #endregion

    #region 오디오 재생 메서드

    public void Play(AudioClip audioClip, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        if (audioClip == null)
            return;

        AudioSource audioSource = _audioSources[(int)type];
        if (audioSource == null) return;

        audioSource.pitch = pitch;

        if (type == Sound.BGM)
        {
            if (audioSource.isPlaying)
                audioSource.Stop();
            audioSource.volume = _bgmSoundVolum;
            audioSource.loop = loop;
            audioSource.clip = audioClip;
            audioSource.Play();
            //성공 로그 출력 
            Debug.Log($"Playing BGM: {audioClip.name} with volume: {_bgmSoundVolum}");
        }
        else // Effect
        {
            audioSource.volume = _effectsoundVolum;
            audioSource.loop = false;
            audioSource.PlayOneShot(audioClip);
        }
    }

    public void Play(string path, Sound type = Sound.SFX, float pitch = 1.0f, bool loop = false)
    {
        AudioClip audioClip = GetAudioClip(path);
        Play(audioClip, type, pitch, loop);
    }

    #endregion

    #region 유틸리티 메서드

    public void VolumSet(Sound type = Sound.SFX, float volum = 1.0f)
    {
        if (type == Sound.BGM)
        {
            _bgmSoundVolum = volum;
            // 현재 재생 중인 BGM의 볼륨을 즉시 업데이트
            if (_audioSources[(int)Sound.BGM] != null)
            {
                _audioSources[(int)Sound.BGM].volume = _bgmSoundVolum;
            }
        }
        else if (type == Sound.SFX)
        {
            _effectsoundVolum = volum;
            // SFX는 PlayOneShot을 사용하므로 다음 재생부터 적용됨

            if (_audioSources[(int)Sound.SFX] != null)
            {
                _audioSources[(int)Sound.SFX].volume = _effectsoundVolum;
            }

            //Debug.Log($"SFX volume updated to: {_effectsoundVolum}");
        }
    }

    AudioClip GetAudioClip(string key)
    {
        if (_audioClips.TryGetValue(key, out AudioClip audioClip))
        {
            return audioClip;
        }

        Debug.LogWarning($"AudioClip not found: {key}");
        return null;
    }

    #endregion
}

using System;
using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;

namespace DogGuns_Games.vamsir
{
    /// <summary>
    /// 플레이어 캐릭터의 기본 동작과 속성을 정의하는 기본 클래스
    /// </summary>
    public class PlayerBase : MonoBehaviour
    {
        #region 플레이어 스탯

        [Header("공격 관련 스탯")]
        public float AttackPower { get; set; }
        public float CoolTime { get; set; }
        public float AttackSpeed { get; set; }
        public float WeaponSize { get; set; }
        public float ProjectileCount { get; set; }
        public float CriticalChance { get; set; }
        public float CriticalDamage { get; set; }

        [Header("방어 및 생존 관련 스탯")]
        public float Health { get; set; }
        public float HealthRegen { get; set; }
        public float Defense { get; set; }
        public float MoveSpeed { get; set; }

        [Header("자원 획득 관련 스탯")]
        public float ExpGain { get; set; }
        public float GoldGain { get; set; }
        public float ItemGainRange { get; set; }
        public float Reroll { get; set; }

        [Header("캐릭터 정보")]
        public float Level { get; set; }
        public Vector3 AttackAngle { get; set; }
        public int characterIndex; // 현재 캐릭터 인덱스

        #endregion

        #region 플레이어 상태 관리

        /// <summary>
        /// 플레이어의 상태를 정의하는 열거형
        /// </summary>
        public enum playerState
        {
            Idle,
            Move,
            Hit,
            Attack
        }

        private playerState _playState;
        public bool ishit = false;
        public Weaphon_base WeaphonBase { get; set; }

        /// <summary>
        /// 플레이어 상태 프로퍼티 - 상태 변경시 SetPlayerState 메서드 호출
        /// </summary>
        public playerState PlayState
        {
            get => _playState;
            set
            {
                _playState = value;
                SetPlayerState(_playState);
            }
        }

        /// <summary>
        /// 플레이어의 상태에 따른 동작 분기 처리
        /// </summary>
        private void SetPlayerState(playerState state)
        {
            switch (state)
            {
                case playerState.Idle:
                    Player_Idle();
                    break;
                case playerState.Move:
                    PlayerMovement();
                    break;
                case playerState.Hit:
                    Player_Hit();
                    break;
                case playerState.Attack:
                    Player_attack(AttackAngle);
                    break;
            }
        }

        #endregion

        #region 초기화

        /// <summary>
        /// 오브젝트가 활성화될 때 호출되는 메서드
        /// </summary>
        public virtual void OnEnable()
        {
        //    InitializeWeapon();
        }

        /// <summary>
        /// 무기 초기화 및 위치 설정
        /// </summary>
        public void InitializeWeapon(Weaphon_base weapon)
        {
            if (weapon != null)
            {
                WeaphonBase = weapon;
                WeaphonBase.transform.SetParent(transform);
                WeaphonBase.transform.localPosition = Vector3.zero;
            }
            else
            {
                Debug.LogWarning("전달된 무기 베이스가 없습니다.");
            }
        }

        #endregion

        #region 충돌 처리

        /// <summary>
        /// 플레이어와 다른 오브젝트 간의 충돌 처리
        /// </summary>
        public virtual void OnCollisionStay2D(Collision2D other)
        {
            GameObject colliderObject = other.gameObject;
            string objectTag = colliderObject.tag;

            switch (objectTag)
            {
                case "Mob":
                    HandleMobCollision(colliderObject);
                    break;
                case "Exp":
                    HandleExpCollision(colliderObject);
                    break;
                case "Coin":
                    HandleCoinCollision(colliderObject);
                    break;
            }
        }

        /// <summary>
        /// 몹과의 충돌 처리 및 피해 계산
        /// </summary>
        /// <param name="mobObject">충돌한 몹 게임오브젝트</param>
        private void HandleMobCollision(GameObject mobObject)
        {
            // 이미 피격 상태면 추가 처리 없음
            if (ishit) return;

            // 피격 상태 설정
            ishit = true;

            // 무적 시간 후 피격 상태 해제 (캔슬레이션 토큰 추가)
            CancellationTokenSource cts = new CancellationTokenSource();
            DelayAction(1f, () => ishit = false, cts.Token).Forget();

            // 피격 상태로 변경
            PlayState = playerState.Hit;

            // 몹으로부터 피해 계산
            VamserMobBase mob = mobObject.GetComponent<VamserMobBase>();
            if (mob != null)
            {
                float damageAmount = CalculateDamage(mob.Mob_AttackDamage);
                ApplyDamage(damageAmount);
            }
        }

        /// <summary>
        /// 방어력을 고려한 최종 피해량 계산
        /// </summary>
        private float CalculateDamage(float rawDamage)
        {
            // 방어력 공식 적용 (방어력이 높을수록 피해 감소)
            return Mathf.Max(1, rawDamage * (100 / (100 + Defense)));
        }

        /// <summary>
        /// 플레이어에게 피해 적용 및 효과 처리
        /// </summary>
        private void ApplyDamage(float damageAmount)
        {
            Health -= damageAmount;

            // 피해량 디버그 로그
            Debug.Log($"플레이어가 {damageAmount:F1} 데미지를 받음 (남은 체력: {Health:F1})");

            // 피격 효과 재생
            PlayHitEffect();
        }

        /// <summary>
        /// 경험치 아이템과의 충돌 처리
        /// </summary>
        private void HandleExpCollision(GameObject expObject)
        {
            EXP_Obj expObj = expObject.GetComponent<EXP_Obj>();
            if (expObj != null && expObj.objectPoolSpawner != null)
            {
                // 경험치 획득 처리 추가
                float expAmount = 1 * ExpGain; // 기본 경험치에 획득 보너스 적용
                Debug.Log($"경험치 {expAmount} 획득");

                // 오브젝트 풀로 반환
                expObj.objectPoolSpawner.ExpObjectPool.Release(expObj);
            }
        }

        /// <summary>
        /// 코인 아이템과의 충돌 처리
        /// </summary>
        private void HandleCoinCollision(GameObject coinObject)
        {
            Coin_Obj coinObj = coinObject.GetComponent<Coin_Obj>();
            if (coinObj != null && coinObj.objectPoolSpawner != null)
            {
                // 코인 획득량에 골드 획득 보너스 적용 가능
                float goldBonus = GoldGain > 0 ? GoldGain : 1;
                int coinsToAdd = Mathf.RoundToInt(1 * goldBonus);

                // 실제 코인 증가
                PlayerDataManagerDontdesytoy.Instance.scritpableobjPlayerData.currency1 += coinsToAdd;
                Debug.Log($"코인 {coinsToAdd}개 획득");

                // 오브젝트 풀로 반환
                coinObj.objectPoolSpawner.CoinObjectPool.Release(coinObj);
            }
        }

        #endregion

        #region 플레이어 액션

        /// <summary>
        /// 플레이어 공격 동작
        /// </summary>
        public virtual void Player_attack(Vector3 attackAngle)
        {
            attackAngle = this.AttackAngle;
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 사망 처리
        /// </summary>
        public virtual void Player_Die()
        {
            Debug.Log("플레이어 사망");
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 피격 동작
        /// </summary>
        public virtual void Player_Hit()
        {
            if (Health <= 0)
            {
                Player_Die();
            }
        }

        /// <summary>
        /// 피격 효과 재생
        /// </summary>
        protected virtual void PlayHitEffect()
        {
            // 애니메이션 효과, 사운드 효과 등 구현
            // AudioManager.Instance.PlaySound("PlayerHit");
            Debug.Log("피격 효과 재생");
        }

        /// <summary>
        /// 플레이어 대기 동작
        /// </summary>
        public virtual void Player_Idle()
        {
            // 자식 클래스에서 구현
        }

        /// <summary>
        /// 플레이어 이동 동작
        /// </summary>
        public virtual void PlayerMovement()
        {
            // 자식 클래스에서 구현
        }

        #endregion

        #region 유틸리티 메서드

        /// <summary>
        /// 지정된 시간 후에 액션을 실행합니다.
        /// </summary>
        /// <param name="delay">지연 시간(초)</param>
        /// <param name="action">실행할 액션</param>
        /// <param name="cancellationToken">취소 토큰(선택 사항)</param>
        /// <returns>UniTask</returns>
        public UniTask DelayAction(float delay, Action action, CancellationToken cancellationToken = default)
        {
            return UniTask.Delay(
                TimeSpan.FromSeconds(delay), 
                cancellationToken: cancellationToken
            ).ContinueWith(() => {
                if (!cancellationToken.IsCancellationRequested)
                {
                    action?.Invoke();
                }
            });
        }

        #endregion
    }
}

